    (s, e) = (pd.Timestamp(start), pd.Timestamp(end) + pd.Timedelta(days=1))
    valid = ct[ct['st_norm'] == 'ok']
    before = set(valid.loc[valid['dt'] < s, 'name_n'])
    during = set(valid.loc[(valid['dt'] >= s) & (valid['dt'] < e), 'name_n'])
